def get_decoders_by_path(query):
    """
    RETURN MAP FROM QUERY PATH TO LIST OF DECODER ARRAYS

    :param query:
    :return:
    """
    decoders = {}
    for path, decoder in query.items():
        if path not in decoders:
            decoders[path] = []
        decoders[path].append(decoder)
    return decoders

